// Логика — как разговор за столом «Моторики»: кто сидит за столом и что важно каждому креслу → «Моторика» и рынок →
// где теряются деньги, время и пользователи (по вашим же документам) → решение: от боли к результату → пакеты работ →
// бизнес-эффект → команда и формат работы → план и пилот → доверие и риски → решения. Заголовок: *слово* выделяется.
// core — маршрут на 20 минут; ch — кресла и читатели, для которых слайд важен (маршруты на сайте).
import { MODEL, r0, r1, bn } from './model.mjs';
import * as D from './data.mjs';

const sc = MODEL.scen;
const SC = { n: D.SCORECARD.length, ahead: D.SCORECARD.filter((r) => r.v === 'ahead').length };
// 1 слайд, 2 слайда, 5 слайдов
export const plural = (n, one, few, many) => { const a = n % 100, b = n % 10; return a > 10 && a < 20 ? many : b === 1 ? one : b > 1 && b < 5 ? few : many; };
const b = sc.base;
// Порядок разделов = порядок слайдов в SLIDES. В скобках — на какой вопрос кресел «Моторики» отвечает раздел.
export const SECTIONS = [
  { id: 'open', t: 'Открытие', q: 'кто за столом и что важно каждому' },
  { id: 'view', t: '«Моторика» и рынок', q: 'где вы сейчас и кто догоняет' },
  { id: 'pain', t: 'Где теряются деньги и пользователи', q: 'что болит — по вашим же документам' },
  { id: 'we', t: 'Решение', q: 'как каждая боль решается и что уже работает' },
  { id: 'wp', t: 'Пакеты работ', q: 'что именно делаем и в какие сроки' },
  { id: 'value', t: 'Бизнес-эффект', q: 'сколько это стоит в деньгах и днях' },
  { id: 'model', t: 'Команда и формат', q: 'кто делает и как работаем вместе' },
  { id: 'plan', t: 'План и пилот', q: 'что будет через 8 недель, 6 и 12 месяцев' },
  { id: 'trust', t: 'Доверие и риски', q: 'данные, нормы, границы и риски' },
  { id: 'next', t: 'Решения', q: 'что решить, чтобы начать' },
];
const ALL = ['ceo', 'cfo', 'product', 'digital', 'rnd', 'med', 'ops', 'reg'];
// Маршрут читателя «Нейротехнологии и инновации» (D.READERS): не кресло за столом, а свой список слайдов
const IN = 'innov';

// Числа эффекта в текстах пакетов работ — из модели
const fill = (s) => s.replace('{ret}', r0(b.retained)).replace('{l1}', r0(b.l1[4])).replace('{doc}', r0(b.docHoursSaved))
  .replace('{visits}', r0(b.visits)).replace('{days}', String(b.pathDays)).replace('{cash}', r0(b.cashPulled)).replace('{fte}', r1(b.onboardFte));
export const WP_EFFECT = Object.fromEntries(D.WPS.map((w) => [w.id, fill(w.eff)]));

const wp = (id) => D.WPS.find((w) => w.id === id);
const wpSlide = (id, ch, notes, src, core = false) => ({ sec: 'wp', layout: 'wp', core, ch, kicker: `${id} · трек «${D.TRACKS.find((t) => t.id === wp(id).tr).t}»`, title: wp(id).t, data: { id }, notes, src });

