// {N} — число слайдов; {#layout} — номер первого слайда с таким макетом, {#wp:WP6} — номер слайда пакета
export function slideOf(ref) {
  const i = ref.startsWith('wp:') ? SLIDES.findIndex((s) => s.layout === 'wp' && s.data.id === ref.slice(3)) : SLIDES.findIndex((s) => s.layout === ref);
  if (i < 0) throw new Error(`нет слайда для ссылки {#${ref}}`);
  return String(i + 1);
}
const resolve = (v) => (typeof v === 'string' ? v.replace(/\{#([\w:]+)\}/g, (_, r) => slideOf(r)).replace(/\{N\}/g, `${SLIDES.length} ${plural(SLIDES.length, 'слайд', 'слайда', 'слайдов')}`) : Array.isArray(v) ? v.map(resolve)
  : v && typeof v === 'object' ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, resolve(x)])) : v);
for (let i = 0; i < SLIDES.length; i++) SLIDES[i] = resolve(SLIDES[i]);

